import sys
lines = sys.stdin.read().splitlines()
if lines:
    parts = lines[0].split()
    cap, m = int(parts[0]), int(parts[1])
    vals = {}
    freqs = {}
    time_stamp = {}
    tick = 0
    out = []
    for line in lines[1:1+m]:
        cmd = line.split()
        if not cmd: continue
        tick += 1
        if cmd[0] == 'PUT':
            k, v = int(cmd[1]), int(cmd[2])
            if cap <= 0: continue
            if k in vals:
                vals[k] = v
                freqs[k] += 1
                time_stamp[k] = tick
            else:
                if len(vals) >= cap:
                    evict = min(vals.keys(), key=lambda x: (freqs[x], time_stamp[x]))
                    del vals[evict]; del freqs[evict]; del time_stamp[evict]
                vals[k] = v
                freqs[k] = 1
                time_stamp[k] = tick
        elif cmd[0] == 'GET':
            k = int(cmd[1])
            if k in vals:
                out.append(str(vals[k]))
                freqs[k] += 1
                time_stamp[k] = tick
            else:
                out.append('-1')
    print(' '.join(out))
